{
  "items": [
    {
      "name": "Algebra.discr_zero_of_not_linearIndependent",
      "module_name": "Mathlib.RingTheory.Discriminant",
      "kind": "theorem",
      "type": "∀ (A : Type u) {B : Type v} {ι : Type w} [inst : DecidableEq ι] [inst_1 : CommRing A] [inst_2 : CommRing B]\n  [inst_3 : Algebra A B] [inst_4 : Fintype ι] [IsDomain A] {b : ι → B}, ¬LinearIndependent A b → Algebra.discr A b = 0"
    },
    {
      "name": "Matrix.gram_apply",
      "module_name": "Mathlib.Analysis.InnerProductSpace.GramMatrix",
      "kind": "theorem",
      "type": "∀ {E : Type u_1} {n : Type u_2} {𝕜 : Type u_4} [inst : Inner 𝕜 E] (v : n → E) (i j : n),\n  Matrix.gram 𝕜 v i j = inner 𝕜 (v i) (v j)"
    },
    {
      "name": "Matrix.det_eq_zero_of_not_linearIndependent_cols",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {m : Type u_1} [inst : DecidableEq m] [inst_1 : Fintype m] {R : Type v} [inst_2 : CommRing R] [IsDomain R]\n  {A : Matrix m m R}, (¬LinearIndependent R fun i => A.transpose i) → A.det = 0"
    },
    {
      "name": "Matrix.det_eq_zero_of_not_linearIndependent_rows",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {m : Type u_1} [inst : DecidableEq m] [inst_1 : Fintype m] {R : Type v} [inst_2 : CommRing R] [IsDomain R]\n  {A : Matrix m m R}, (¬LinearIndependent R fun i => A i) → A.det = 0"
    },
    {
      "name": "Polynomial.derivativeFinsupp",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Semiring R] → Polynomial R →ₗ[R] ℕ →₀ Polynomial R"
    },
    {
      "name": "Matrix.linearIndependent_cols_of_det_ne_zero",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {m : Type u_1} [inst : DecidableEq m] [inst_1 : Fintype m] {R : Type v} [inst_2 : CommRing R] [IsDomain R]\n  {A : Matrix m m R}, A.det ≠ 0 → LinearIndependent R A.col"
    },
    {
      "name": "Matrix.det_vandermonde_eq_zero_iff",
      "module_name": "Mathlib.LinearAlgebra.Vandermonde",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {n : ℕ} [IsDomain R] {v : Fin n → R},\n  (Matrix.vandermonde v).det = 0 ↔ ∃ i j, v i = v j ∧ i ≠ j"
    },
    {
      "name": "Matrix.det_vandermonde_ne_zero_iff",
      "module_name": "Mathlib.LinearAlgebra.Vandermonde",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {n : ℕ} [IsDomain R] {v : Fin n → R},\n  (Matrix.vandermonde v).det ≠ 0 ↔ Function.Injective v"
    }
  ]
}
